func twoSumSortedIndices(_ numbers: [Int], target: Int) -> [Int] {
    var left = 0
    var right = numbers.count - 1
    while left < right {
        let sum = numbers[left] + numbers[right]
        if sum == target {
            return [left, right]
        } else if sum < target {
            left += 1
        } else {
            right -= 1
        }
    }
    return []
}

let values = [2, 7, 11, 15]
print(twoSumSortedIndices(values, target: 9))
print(twoSumSortedIndices(values, target: 50))

func maxSlidingWindowSum(_ nums: [Int], k: Int) -> Int {
    guard nums.count >= k, k > 0 else { return 0 }
    var windowSum = 0
    for i in 0 ..< k {
        windowSum += nums[i]
    }
    var maxSum = windowSum
    for i in k ..< nums.count {
        windowSum += nums[i] - nums[i - k]
        maxSum = max(maxSum, windowSum)
    }
    return maxSum
}

print(maxSlidingWindowSum([2, 1, 5, 1, 3, 2], k: 3))
print(maxSlidingWindowSum([4, 2, 1, 7, 8, 1, 2], k: 3))

func removeDuplicates(_ nums: inout [Int]) -> Int {
    guard !nums.isEmpty else { return 0 }
    var write = 1
    for read in 1 ..< nums.count {
        if nums[read] != nums[read - 1] {
            nums[write] = nums[read]
            write += 1
        }
    }
    return write
}

var values = [1, 1, 2, 3, 3, 4]
let count = removeDuplicates(&values)
print("\(count): \(values[0 ..< count])")
